/**
 * Familias Google Fonts autocontenidas (OFL-1.1) para el tema de una tienda.
 *
 * Cada familia viaja como woff2 variable latin embebido en base64: el export
 * self-hosted escribe `assets/fonts/<id>.woff2` y el preview lo transporta
 * inline (el iframe se renderiza con srcDoc y no resuelve URLs relativas).
 * El registro es la única fuente de familias conocidas: un stack persistido
 * que no matchea ninguna no emite @font-face y el navegador cae al fallback.
 */
export type FontTransport = "file" | "inline";

export interface FontOption {
  id: string;
  label: string;
  family: string;
  stack: string;
  weightRange: string;
  license: string;
  woff2Path: string;
  woff2Base64: string;
}

function base64ToBytes(value: string): Uint8Array {
  if (typeof atob === "function") {
    const binary = atob(value);
    return Uint8Array.from(binary, (character) => character.charCodeAt(0));
  }
  return Uint8Array.from(Buffer.from(value, "base64"));
}

export const FONT_OPTIONS: readonly FontOption[] = [
  {
    id: "gf-archivo",
    label: "Archivo",
    family: "Archivo",
    stack: 'Archivo, "Arial Narrow", "Helvetica Neue", Arial, sans-serif',
    weightRange: "400 900",
    license: "OFL-1.1",
    woff2Path: "assets/fonts/archivo.woff2",
    woff2Base64: "",
  },
  {
    id: "gf-inter",
    label: "Inter",
    family: "Inter",
    stack: 'Inter, system-ui, "Segoe UI", Arial, sans-serif',
    weightRange: "400 900",
    license: "OFL-1.1",
    woff2Path: "assets/fonts/inter.woff2",
    woff2Base64: "",
  },
  {
    id: "gf-lora",
    label: "Lora",
    family: "Lora",
    stack: 'Lora, Georgia, "Times New Roman", serif',
    weightRange: "400 700",
    license: "OFL-1.1",
    woff2Path: "assets/fonts/lora.woff2",
    woff2Base64: "",
  },
];

const FONT_BY_FAMILY: ReadonlyMap<string, FontOption> = new Map(
  FONT_OPTIONS.map((option) => [option.family.toLowerCase(), option]),
);

/** Resuelve la familia Google de un stack persistido (primer nombre, sin comillas). */
export function fontOptionForStack(stack: string | undefined): FontOption | undefined {
  const first = stack?.split(",")[0]?.trim().replace(/^["']+|["']+$/g, "");
  if (!first) return undefined;
  return FONT_BY_FAMILY.get(first.toLowerCase());
}

/** Familias en uso, deduplicadas: display === body emite un solo @font-face/archivo. */
export function activeFonts(display: string, body: string): readonly FontOption[] {
  const fonts: FontOption[] = [];
  for (const stack of [display, body]) {
    const option = fontOptionForStack(stack);
    if (option && !fonts.some((font) => font.id === option.id)) fonts.push(option);
  }
  return fonts;
}

/** CSS @font-face del tema: URL relativa en el export o data URI en el preview. */
export function fontCssFor(
  display: string,
  body: string,
  transport: FontTransport = "file",
  filePathOverrides?: ReadonlyMap<string, string>,
): string {
  const src = (option: FontOption): string =>
    transport === "inline"
      ? `url("data:font/woff2;base64,${option.woff2Base64}") format("woff2")`
      : `url("/${filePathOverrides?.get(option.woff2Path) ?? option.woff2Path}") format("woff2")`;
  return activeFonts(display, body)
    .map(
      (option) =>
        `@font-face{font-family:"${option.family}";src:${src(option)};font-display:swap;font-weight:${option.weightRange}}`,
    )
    .join("");
}

/** Archivos woff2 del sitio exportado para las familias en uso. */
export function fontFilesFor(display: string, body: string): ReadonlyMap<string, Uint8Array> {
  const files = new Map<string, Uint8Array>();
  activeFonts(display, body).forEach((option) => {
    files.set(option.woff2Path, base64ToBytes(option.woff2Base64));
  });
  return files;
}
